import dask.dataframe as dd
import pandas as pd

pdf = pd.DataFrame({"email": ["Ana@X.com", "ben@y.org", "cy@X.COM", "di@z.net"],
                    "spend": [10.0, 20.0, 30.0, 40.0]})
df = dd.from_pandas(pdf, npartitions=2)

def enrich(part: pd.DataFrame) -> pd.DataFrame:
    domain = part["email"].str.split("@").str[1].str.lower()
    return part.assign(domain=domain, vip=part["spend"] > 25)

meta = {"email": "string", "spend": "float64", "domain": "string", "vip": "bool"}
out = df.map_partitions(enrich, meta=meta)
print(out.dtypes.astype(str).to_dict())
# {'email': 'string', 'spend': 'float64', 'domain': 'string', 'vip': 'bool'}
print(out.groupby("domain").spend.sum().compute().sort_index().to_dict())
# {'x.com': 40.0, 'y.org': 20.0, 'z.net': 40.0}
